<?php
namespace App\Http\Controllers\Modules\oms;
use App\Http\Controllers\Controller; use App\Models\modules\oms\BilledOrderLine; use App\Models\modules\oms\OrderNote; use App\Models\prestashop\suppliers; use App\Services\Prestashop\PrestashopAdminLinkService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class SimplifiedOrderNoteController extends Controller {
 public function index(Request $request){$sid=(int)$request->integer('supplier_id');$suppliers=suppliers::select(['id_supplier','name'])->orderBy('name')->get();$notes=$sid?OrderNote::where('supplier_id',$sid)->latest()->get(['id','supplier_id','reference','status','created_at']):collect();$note=$notes->firstWhere('id',(int)$request->integer('order_note_id'))??$notes->first();if($note)$note->load(['supplier','lines']);return view('modules.oms.order_notes.simplified',['suppliers'=>$suppliers,'selectedSupplierId'=>$sid,'orderNotes'=>$notes,'orderNote'=>$note,'simplifiedOmsRows'=>$note?$this->rows($note):collect()]);}
 private function rows(OrderNote $note){$lines=$note->lines;$ids=$lines->pluck('id')->filter();if($ids->isEmpty())return collect();$x=(string)(env('DB2_prefix')?:env('DB2_DB_prefix')?:'ps_');$inv=BilledOrderLine::whereIn('order_note_line_id',$ids)->selectRaw('order_note_line_id,SUM(qty_billed) q')->groupBy('order_note_line_id')->pluck('q','order_note_line_id');$rec=DB::table('oms_reception_lines as r')->join('oms_billed_order_lines as b','b.id','=','r.billed_order_line_id')->whereIn('b.order_note_line_id',$ids)->selectRaw('b.order_note_line_id,SUM(r.qty_received) q')->groupBy('b.order_note_line_id')->pluck('q','b.order_note_line_id');$pids=$lines->pluck('product_id')->filter()->unique();$aids=$lines->pluck('product_attribute_id')->filter()->unique();$p=DB::connection('mysql2')->table($x.'product as p')->leftJoin($x.'product_lang as l','l.id_product','=','p.id_product')->leftJoin($x.'custom_product as cp','cp.id_product','=','p.id_product')->whereIn('p.id_product',$pids)->groupBy('p.id_product','p.reference','p.location','p.wholesale_price','p.price','cp.dim_verify','cp.wholesale_price_base_currency','cp.price_base_currency')->selectRaw('p.id_product,p.reference,p.location housing,p.wholesale_price purchase_eur,p.price sales_eur,COALESCE(cp.dim_verify,0) dim_verify,COALESCE(cp.wholesale_price_base_currency,0) purchase_supplier,COALESCE(cp.price_base_currency,0) sales_supplier,MIN(l.name) name')->get()->keyBy('id_product');$a=$aids->isEmpty()?collect():DB::connection('mysql2')->table($x.'product_attribute as a')->leftJoin($x.'custom_product_attribute as ca',function($j){$j->on('ca.id_product_attribute','=','a.id_product_attribute')->on('ca.id_product','=','a.id_product');})->whereIn('a.id_product_attribute',$aids)->selectRaw('a.id_product_attribute,a.reference,ca.location housing,a.wholesale_price purchase_eur,a.price sales_eur,COALESCE(ca.wholesale_price_base_currency,0) purchase_supplier,COALESCE(ca.price_base_currency,0) sales_supplier')->get()->keyBy('id_product_attribute');$bo=$this->backorders($pids,$x);return $lines->map(function($l)use($p,$a,$inv,$rec,$bo){$pr=$p->get($l->product_id);$at=$l->product_attribute_id?$a->get($l->product_attribute_id):null;$key=(int)$l->product_id.'|'.(int)($l->product_attribute_id??0);$attr=(bool)$at;return ['line_id'=>(int)$l->id,'reference'=>trim((string)($at->reference??$pr->reference??''))?:'—','name'=>trim((string)($pr->name??''))?:'Product #'.$l->product_id,'housing'=>trim((string)($at->housing??$pr->housing??'')),'dim_verified'=>(int)($pr->dim_verify??0)===1,'backorders'=>$bo->get($key,collect())->values(),'ordered'=>(int)$l->qty_ordered,'invoiced'=>(int)($inv[$l->id]??0),'received'=>(int)($rec[$l->id]??0),'purchase_supplier'=>(float)($attr?$at->purchase_supplier:$pr->purchase_supplier),'purchase_eur'=>(float)($attr?$at->purchase_eur:$pr->purchase_eur),'sales_supplier'=>(float)($attr?($pr->sales_supplier+$at->sales_supplier):$pr->sales_supplier),'sales_eur'=>(float)($attr?($pr->sales_eur+$at->sales_eur):$pr->sales_eur),'currency_iso'=>''];});}
 private function backorders($ids,string $x){return DB::connection('mysql2')->table($x.'order_detail as d')->join($x.'orders as o','o.id_order','=','d.id_order')->join($x.'stock_available as s',function($j){$j->on('s.id_product','=','d.product_id')->on('s.id_product_attribute','=','d.product_attribute_id')->where('s.id_shop',0);})->where('o.current_state',15)->where('s.quantity','<',0)->whereIn('d.product_id',$ids)->select(['o.id_order','o.reference','o.id_shop','d.product_id','d.product_attribute_id','s.quantity as stock'])->get()->map(function($r){$r->store=(int)$r->id_shop===3?'ASD':'ASM';$r->url=PrestashopAdminLinkService::dashboardOrderAdminUrl((int)$r->id_order,$r->store);return $r;})->groupBy(fn($r)=>(int)$r->product_id.'|'.(int)$r->product_attribute_id);}
}
